/**
 * @param {number[][]} bottomLeft
 * @param {number[][]} topRight
 * @return {number}
 */
var largestSquareArea = function (bottomLeft, topRight) {
    const n = bottomLeft.length;
    let maxSide = 0;

    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            const [b1w, b1h] = bottomLeft[i];
            const [t1w, t1h] = topRight[i];
            const [b2w, b2h] = bottomLeft[j];
            const [t2w, t2h] = topRight[j];

            const w = Math.min(t1w, t2w) - Math.max(b1w, b2w);
            const h = Math.min(t1h, t2h) - Math.max(b1h, b2h);

            maxSide = Math.max(maxSide, Math.min(w, h));
        }
    }

    return maxSide * maxSide;
};
